CREATE OR REPLACE FUNCTION public.fn_create_or_update_organization_entitlement(p_id uuid, p_tenant_id uuid, p_organization_id uuid, p_platform_experience_id uuid, p_order_id uuid, p_acquired_version integer, p_entitlement_type character varying, p_status character varying, p_granted_at timestamp with time zone, p_expires_at timestamp with time zone, p_scope character varying)  RETURNS SETOF organization_entitlements  LANGUAGE sql AS $function$     INSERT INTO organization_entitlements (         id, tenant_id, organization_id, platform_experience_id, order_id,         acquired_version, entitlement_type, status, granted_at, expires_at, scope     ) VALUES (         p_id, p_tenant_id, p_organization_id, p_platform_experience_id, p_order_id,         p_acquired_version, p_entitlement_type, p_status, p_granted_at, p_expires_at, p_scope     )     ON CONFLICT (organization_id, platform_experience_id) DO UPDATE     SET acquired_version = EXCLUDED.acquired_version,         status = EXCLUDED.status,         expires_at = EXCLUDED.expires_at     RETURNING *; $function$ ;
